import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"離下震上 豐：","description":"京氏易傳 - 離下震上 豐：","frontmatter":{"title":"離下震上 豐：","description":"京氏易傳 - 離下震上 豐："},"headers":[],"relativePath":"classics/jingshi/023.md","filePath":"classics/jingshi/023.md"}'),r={name:"classics/jingshi/023.md"};function l(c,a,o,d,p,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"離下震上-豐",tabindex:"-1"},[i("離下震上 豐： "),e("a",{class:"header-anchor",href:"#離下震上-豐","aria-label":"Permalink to “離下震上 豐：”"},"​")],-1),e("p",null,"雷火交動，剛柔散氣，積則暗，動乃明。《易》雲：“豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，兇。”【上六積暗而動，兇之於上反下，見陰之兆。】火木分象，配於積陰，與震為飛伏。【庚申金，戊戌土。】陰處至尊為世，大夫見應。君臣相暗，世則可知；臣強君弱，為亂世之始。",-1),e("p",null,"建生戊子至癸巳，【大雪至小滿。】雷與火震動曰豐。宜日中。夏至積陰生豐，當正應，吉凶見矣。【日中也。】積算起癸巳至壬辰，週而復始。【火土起算。】",-1),e("p",null,"五星從位起太白，【太白金星入卦。】壁宿從位降庚申，【壁宿入坎至豐，庚申入土。】分氣候二十八。【積算定六位，起數二十八。】",-1),e("p",null,"上木下火，氣稟純陽；陰生於內，陽氣雜正，性潰亂極，乃反為遊魂，入積陰。【震入坤也。】陰陽升降，反歸於本。變體於有無。吉凶之兆，或見於有，或見於無。陰陽之體，不可執一。為定象於八卦，陽蕩陰，陰蕩陽，二氣相感而成體，或隱或顯。故《系》雲：“一陰一陽之謂道。”【一者，道也。】外卦震降陰，入明夷。【次入明夷卦。】",-1)])])}const h=s(r,[["render",l]]);export{f as __pageData,h as default};
